// Arquivo: pages/_middleware.ts
import { NextResponse } from 'next/server';

/**
 * Middleware que garante respostas consistentes independentemente do User‑Agent.
 * 
 * Anteriormente a aplicação redirecionava usuários móveis para páginas
 * específicas e alterava o status code para 302 quando detectava crawlers.
 * Isso criava diferenças visíveis no corpo da resposta, permitindo
 * que um fuzzer de User‑Agent identificasse a lógica de negócio.
 *
 * A correção remove todas as verificações condicionais baseadas em
 * `req.headers.get('user-agent')` e garante que a mesma rota seja
 * servida para todos os clientes. Caso seja necessário servir
 * conteúdo otimizado, a lógica deve ser movida para o lado do cliente
 * (ex.: CSS responsivo ou JavaScript que detecta o dispositivo).
 */
export function middleware(req) {
  // Apenas passamos a requisição para o Next.js sem alterar nada.
  return NextResponse.next();
}

